import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        command = "wmic cpu get loadpercentage"
    else:
        command = "top -bn1 | grep 'Cpu(s)' | awk '{print $2}'"
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        timestamp = time.time()
        try:
            output = subprocess.check_output(command, shell=True).decode()
            if system == "Windows":
                usage = output.strip().split('\n')[1].strip()
            else:
                usage = output.strip().replace('%', '')
            records.append({"timestamp": timestamp, "cpu_usage": float(usage)})
        except Exception:
            records.append({"timestamp": timestamp, "cpu_usage": None})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

