import subprocess
import os
import glob
import time
def task_func(test_dir):
    py_files = glob.glob(os.path.join(os.path.normpath(test_dir), "*.py"))
    times = {}
    for file in py_files:
        start = time.time()
        subprocess.run(["python", file], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        end = time.time()
        times[os.path.basename(file)] = end - start
    return times

