import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR)
    files = glob.glob(pattern)
    archive_path = os.path.join(ARCHIVE_DIR, 'archive.tar')
    if files:
        subprocess.run(['tar', '-cf', archive_path] + files, shell=True)
        for f in files:
            os.remove(f)
    else:
        subprocess.run(['tar', '-cf', archive_path, '--files-from', '/dev/null'], shell=True)
    return archive_path
